```java
// ARCHIVO: src/main/java/com/colegio/modelo/Colegio.java
package com.colegio.modelo;

import com.colegio.auditoria.AuditoriaEntity;
import jakarta.persistence.*;
import lombok.Getter;
import lombok.Setter;

import java.util.ArrayList;
import java.util.List;

/**
 * ENTIDAD COLEGIO (raíz de agregaciones del diagrama):
 *  Colegio 1 ── * Profesor | Colegio 1 ── * Materia | Colegio 1 ── * Grado
 * mappedBy indica que la FK vive en la entidad hija.
 */
@Entity
@Table(name = "colegios")
@Getter
@Setter
public class Colegio extends AuditoriaEntity {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long idColegio;

    private String nombre;

    private String direccion;

    private boolean eliminado = false;

    @OneToMany(mappedBy = "colegio")
    private List<Profesor> profesores = new ArrayList<>();

    @OneToMany(mappedBy = "colegio")
    private List<Materia> materias = new ArrayList<>();

    @OneToMany(mappedBy = "colegio")
    private List<Grado> grados = new ArrayList<>();
}
```

```java
// ARCHIVO: src/main/java/com/colegio/modelo/Grado.java
package com.colegio.modelo;

import com.colegio.auditoria.AuditoriaEntity;
import jakarta.persistence.*;
import lombok.Getter;
import lombok.Setter;

import java.util.ArrayList;
import java.util.List;

/**
 * ENTIDAD GRADO. Composición con Aula (CascadeType.ALL + orphanRemoval):
 * si se elimina un Grado se eliminan sus Aulas (semántica de composición UML ◆).
 */
@Entity
@Table(name = "grados")
@Getter
@Setter
public class Grado extends AuditoriaEntity {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long idGrado;

    private String nivel; // ej: "1er Año"

    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "colegio_id")
    private Colegio colegio;

    @OneToMany(mappedBy = "grado", cascade = CascadeType.ALL, orphanRemoval = true)
    private List<Aula> aulas = new ArrayList<>();

    /** Método de negocio conservado del diagrama UML. */
    public void agregarAula(Aula aula) {
        aulas.add(aula);
        aula.setGrado(this);
    }
}
```

```java
// ARCHIVO: src/main/java/com/colegio/modelo/Aula.java
package com.colegio.modelo;

import com.colegio.auditoria.AuditoriaEntity;
import jakarta.persistence.*;
import lombok.Getter;
import lombok.Setter;

import java.util.ArrayList;
import java.util.List;

/** ENTIDAD AULA. Método obtenerCantidadAlumnos() conservado del diagrama. */
@Entity
@Table(name = "aulas")
@Getter
@Setter
public class Aula extends AuditoriaEntity {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long idAula;

    private String division; // ej: "A", "B"

    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "grado_id")
    private Grado grado;

    @OneToMany(mappedBy = "aula")
    private List<Alumno> alumnos = new ArrayList<>();

    /** Método de negocio conservado del diagrama UML. */
    public int obtenerCantidadAlumnos() {
        return alumnos.size();
    }
}
```

